package elseborn.packfix;

import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
import java.util.logging.Logger;
import java.util.zip.*;

/** Lossless, format-75-only cleanup of aliases generated by PackRepair. */
public final class AtlasCanonicalizer {
    private static final Gson G = new GsonBuilder().disableHtmlEscaping().create();
    private static final String PREFIX = "assets/elseborn_compat/models/itemfix/";
    private static String type(JsonObject o) { return o.has("type") ? o.get("type").getAsString().replace("minecraft:", "") : ""; }
    private static String id(String s) { return s.contains(":") ? s : "minecraft:" + s; }
    private static String sprite(JsonObject o) { return id(o.has("sprite") ? o.get("sprite").getAsString() : o.get("resource").getAsString()); }
    private static int major(JsonElement e) { return e.isJsonArray() ? e.getAsJsonArray().get(0).getAsInt() : e.getAsInt(); }
    private static boolean active(JsonObject e) {
        int lo = e.has("min_format") ? major(e.get("min_format")) : 0;
        int hi = e.has("max_format") ? major(e.get("max_format")) : Integer.MAX_VALUE;
        if (e.has("formats")) {
            JsonElement f = e.get("formats");
            if (f.isJsonObject()) {lo = f.getAsJsonObject().get("min_inclusive").getAsInt();hi = f.getAsJsonObject().get("max_inclusive").getAsInt();}
            else if (f.isJsonArray()) {lo = f.getAsJsonArray().get(0).getAsInt();hi = f.getAsJsonArray().get(1).getAsInt();}
            else lo = hi = f.getAsInt();
        }
        return lo <= 75 && hi >= 75;
    }
    private static void refs(JsonElement e, Set<String> out) {
        if (e.isJsonPrimitive() && e.getAsJsonPrimitive().isString()) out.add(e.getAsString());
        else if (e.isJsonArray()) for (JsonElement v : e.getAsJsonArray()) refs(v,out);
        else if (e.isJsonObject()) {
            JsonObject o=e.getAsJsonObject();
            for (var v:o.asMap().entrySet()) {
                // Model and sprite registries may use the same textual ID.
                if(v.getKey().equals("model") && type(o).equals("model") && v.getValue().isJsonPrimitive()) continue;
                refs(v.getValue(),out);
            }
        }
    }
    private static void allRefs(JsonElement e, Set<String> out) {
        if(e.isJsonPrimitive() && e.getAsJsonPrimitive().isString()) out.add(e.getAsString());
        else if(e.isJsonArray()) for(JsonElement v:e.getAsJsonArray()) allRefs(v,out);
        else if(e.isJsonObject()) for(JsonElement v:e.getAsJsonObject().asMap().values()) allRefs(v,out);
    }
    private static int nodes(JsonElement e, Map<String,String> redirects) {
        int count = 0;
        if (e.isJsonArray()) for (JsonElement v : e.getAsJsonArray()) count += nodes(v,redirects);
        else if (e.isJsonObject()) {
            JsonObject o=e.getAsJsonObject();
            String field=type(o).equals("model") ? "model" : type(o).equals("special") ? "base" : null;
            if (field!=null && o.has(field) && o.get(field).isJsonPrimitive()) {
                String key=id(o.get(field).getAsString());
                if (redirects.containsKey(key)) {o.addProperty(field,redirects.get(key));count++;}
            }
            for (JsonElement v : o.asMap().values()) count += nodes(v,redirects);
        }
        return count;
    }
    public static void optimize(Path pack) throws Exception {
        Path temp=null;
        try {
            Map<String,byte[]> changed=new LinkedHashMap<>();
            int aliases=0, entries=0, models=0, links=0, removedModels=0;
            try (ZipFile z=new ZipFile(pack.toFile())) {
                JsonObject meta=JsonParser.parseString(new String(z.getInputStream(z.getEntry("pack.mcmeta")).readAllBytes(),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();
                JsonObject fmt=meta.getAsJsonObject("pack");
                if (!(fmt.has("min_format") && major(fmt.get("min_format"))==75 && fmt.has("max_format") && major(fmt.get("max_format"))==75)) throw new IllegalStateException("Expected pinned format 75");
                Map<String,String> effective=new LinkedHashMap<>();
                List<? extends ZipEntry> files=Collections.list(z.entries());
                for (ZipEntry e:files) if (e.getName().startsWith("assets/") && !e.isDirectory()) effective.put(e.getName(),e.getName());
                if (meta.has("overlays")) for (JsonElement value:meta.getAsJsonObject("overlays").getAsJsonArray("entries")) {
                    JsonObject e=value.getAsJsonObject();if (!active(e)) continue;
                    String prefix=e.get("directory").getAsString()+"/";
                    for (ZipEntry f:files) if (f.getName().startsWith(prefix+"assets/") && !f.isDirectory()) effective.put(f.getName().substring(prefix.length()),f.getName());
                }
                Map<String,JsonObject> docs=new LinkedHashMap<>();
                for (var e:effective.entrySet()) if (e.getKey().endsWith(".json")) {
                    JsonElement v=JsonParser.parseString(new String(z.getInputStream(z.getEntry(e.getValue())).readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));
                    if (v.isJsonObject()) docs.put(e.getKey(),v.getAsJsonObject());
                }
                String ip="assets/minecraft/atlases/items.json";
                JsonObject atlas=docs.get(ip);if (atlas==null) return;
                JsonArray sources=atlas.getAsJsonArray("sources");
                Map<String,Set<String>> groups=new TreeMap<>();
                Map<String,Set<String>> resolutions=new HashMap<>();
                Set<String> otherAtlas=new HashSet<>(),external=new HashSet<>();
                for (var e:docs.entrySet()) {
                    if (e.getKey().contains("/atlases/") && !e.getKey().equals(ip) && e.getValue().has("sources")) {
                        for (JsonElement v:e.getValue().getAsJsonArray("sources")) {JsonObject o=v.getAsJsonObject();if(type(o).equals("single")) otherAtlas.add(sprite(o));}
                    } else if (!e.getKey().equals(ip) && !e.getKey().startsWith(PREFIX)) refs(e.getValue(),external);
                }
                for (JsonElement v:sources) {
                    JsonObject o=v.getAsJsonObject();
                    if (!type(o).equals("single")) continue;
                    String res=id(o.get("resource").getAsString()),sp=sprite(o);
                    groups.computeIfAbsent(res,k->new TreeSet<>()).add(sp);
                    resolutions.computeIfAbsent(sp,k->new HashSet<>()).add(res);
                }
                Map<String,String> remap=new HashMap<>();
                for (Set<String> group:groups.values()) {
                    String canonical=group.stream().filter(s->!s.startsWith("elseborn_compat:") && !otherAtlas.contains(s) && resolutions.get(s).size()==1).findFirst().orElse(null);
                    if (canonical==null) continue;
                    for (String s:group) if (s.startsWith("elseborn_compat:itemfix/") && !otherAtlas.contains(s) && !external.contains(s) && resolutions.get(s).size()==1) remap.put(s,canonical);
                }
                Set<String> dirty=new HashSet<>();
                for (var e:docs.entrySet()) if (e.getKey().startsWith(PREFIX) && e.getValue().has("textures")) {
                    JsonObject tex=e.getValue().getAsJsonObject("textures");
                    for (String k:new ArrayList<>(tex.keySet())) {
                        String old=tex.get(k).getAsString();
                        if(remap.containsKey(old)) {tex.addProperty(k,remap.get(old));dirty.add(e.getKey());links++;}
                    }
                }
                // A generated alias may be referenced in unusual fields. Keep such aliases.
                Set<String> remaining=new HashSet<>();
                for (var e:docs.entrySet()) if(!e.getKey().contains("/atlases/")) refs(e.getValue(),remaining);
                JsonArray clean=new JsonArray();Set<JsonElement> seen=new HashSet<>();
                for (JsonElement v:sources) {
                    JsonObject o=v.getAsJsonObject();
                    if(type(o).equals("single") && remap.containsKey(sprite(o)) && !remaining.contains(sprite(o))) {aliases++;continue;}
                    if(type(o).equals("single") && !seen.add(o)) {entries++;continue;}
                    clean.add(v);
                }
                atlas.add("sources",clean);dirty.add(ip);
                // Redirect only structurally identical generated models, leaving every file intact.
                Map<String,String> redirects=new HashMap<>();
                boolean progress;
                do {
                    progress=false;
                    for (var e:docs.entrySet()) if(e.getKey().startsWith(PREFIX)) {
                        JsonObject d=e.getValue();
                        if(d.has("parent")) {String old=id(d.get("parent").getAsString());if(redirects.containsKey(old)){d.addProperty("parent",redirects.get(old));dirty.add(e.getKey());}}
                        String tail=e.getKey().substring(PREFIX.length()),key="elseborn_compat:itemfix/"+tail.substring(0,tail.length()-5);
                        int slash=tail.indexOf('/');if(slash<1)continue;
                        String original="assets/"+tail.substring(0,slash)+"/models/"+tail.substring(slash+1);
                        if(!redirects.containsKey(key) && docs.containsKey(original) && d.equals(docs.get(original))) {
                            redirects.put(key,tail.substring(0,slash)+":"+tail.substring(slash+1,tail.length()-5));progress=true;
                        }
                    }
                } while(progress);
                Map<JsonObject,String> identical=new HashMap<>();
                List<String> modelPaths=new ArrayList<>();
                for(String key:docs.keySet()) if(key.matches("assets/[^/]+/models/.+\\.json")) modelPaths.add(key);
                modelPaths.sort(Comparator.comparing((String k)->k.startsWith(PREFIX)).thenComparing(k->k));
                for(String key:modelPaths) {
                    String rid=key.substring(7).replaceFirst("/models/",":");rid=rid.substring(0,rid.length()-5);
                    String canonical=identical.putIfAbsent(docs.get(key),rid);
                    if(canonical!=null && !canonical.equals(rid)) redirects.put(rid,canonical);
                }
                for (var e:docs.entrySet()) if(e.getKey().matches("assets/[^/]+/items/.+\\.json") && nodes(e.getValue(),redirects)>0) dirty.add(e.getKey());
                Set<String> used=new HashSet<>();
                for(JsonObject doc:docs.values()) allRefs(doc,used);
                Set<String> omit=new HashSet<>();
                for(String key:modelPaths) if(key.startsWith(PREFIX)) {
                    String rid="elseborn_compat:itemfix/"+key.substring(PREFIX.length(),key.length()-5);
                    if(!used.contains(rid)) omit.add(effective.get(key));
                }
                removedModels=omit.size();
                models=redirects.size();
                for(String key:dirty) changed.put(effective.get(key),G.toJson(docs.get(key)).getBytes(java.nio.charset.StandardCharsets.UTF_8));
                temp=Files.createTempFile(pack.getParent(),"atlas-canonical-",".zip");
                Set<String> written=new HashSet<>();
                try(ZipOutputStream out=new ZipOutputStream(Files.newOutputStream(temp))) {
                    for(ZipEntry e:files) {
                        if(omit.contains(e.getName())) continue;
                        if(!written.add(e.getName()))throw new IllegalStateException("Duplicate ZIP entry");
                        out.putNextEntry(new ZipEntry(e.getName()));
                        if(changed.containsKey(e.getName())) out.write(changed.get(e.getName()));
                        else try(var in=z.getInputStream(e)){in.transferTo(out);}
                        out.closeEntry();
                    }
                }
                try(ZipInputStream in=new ZipInputStream(Files.newInputStream(temp))){while(in.getNextEntry()!=null)in.transferTo(java.io.OutputStream.nullOutputStream());}
            }
            Files.move(temp,pack,StandardCopyOption.REPLACE_EXISTING);temp=null;
            Logger.getLogger("ElsebornPackFix").info("Atlas canonicalization: "+entries+" exact repeated entries, "+aliases+" repeated alias entries removed; "+links+" texture links and "+models+" identical model redirects; "+removedModels+" unreferenced generated models omitted; all native models and texture bytes retained.");
        } finally {if(temp!=null)Files.deleteIfExists(temp);}
    }
    public static void main(String[] args) throws Exception {optimize(Path.of(args[0]));}
}
